  ["Escaneando la AH (%d%%): espera a que acabe para anunciar al precio de ahora."] = "Scanning the AH (%d%%): wait until it finishes to post at current prices.",
  ["Escaneando la AH (%d%%): espera para anunciar al precio de ahora."] = "Scanning the AH (%d%%): wait to post at current prices.",
  ["Precios de hace %d h: pueden haber cambiado. Escanea antes de anunciar."] = "Prices from %d h ago: they may have changed. Scan before posting.",
  ["Escaneando la AH... %d%%"] = "Scanning the AH... %d%%",
