  ["Anunciados %d de %s a %s cada uno (%d h)."] = "Posted %d %s at %s each (%d h).",
  ["Subasta de %d h: no se sabe si se vende y, si caduca, pierdes solo %s de depósito por subasta."] = "%d h auction: it's not known whether it sells, and if it expires you only lose %s deposit per auction.",
  ["No llevas %s en las bolsas."] = "You don't have %s in your bags.",
  ["Lo que tienes se usa primero; el resto se compra (arriba)"] = "What you have is used first; the rest is bought (above)",
  ["Empezar ruta"] = "Start route",
  ["Fija esta ruta: mientras compras en la AH, al vendedor o sacas del correo, ni la ruta ni su coste cambian. La lista de la compra va marcando lo que te falta."] = "Locks this route: while you buy on the AH, from vendors or take items from your mailbox, neither the route nor its cost change. The shopping list keeps track of what you still need.",
  ["Púlsalo antes de empezar a comprar."] = "Click it before you start buying.",
  ["Ruta en curso (de %d a %d): lo que compras no cambia la ruta ni su coste"] = "Route in progress (%d to %d): what you buy doesn't change the route or its cost",
  [" · hay precios nuevos de la AH|r"] = " · new AH prices|r",
  [" · precios nuevos: %s más|r"] = " · new prices: %s more|r",
  [" · precios nuevos: %s menos|r"] = " · new prices: %s less|r",
  ["Con el último escaneo, lo que te queda cuesta %s (con los precios de tu ruta, %s)."] = "With your latest scan, the rest of your route costs %s (%s with your route's prices).",
  ["Con el último escaneo, lo que te queda de tu ruta de %s cuesta %s más (%s en vez de %s). Ábrela y pulsa Actualizar precios para verla con estos precios."] = "With your latest scan, the rest of your %s route costs %s more (%s instead of %s). Open it and press Update prices to see it with these prices.",
  ["Actualizar precios"] = "Update prices",
  ["La misma ruta (mismas recetas en cada nivel) con los precios del último escaneo. Lo que llevas gastado y vendido se mantiene."] = "The same route (same recipes at each level) with the prices from the latest scan. What you've spent and sold so far is kept.",
  
  [" · pulsa Empezar ruta antes de comprar|r"] = " · click Start route before buying|r",
