  ["%d/%d puntos · ~%s%d|r fabricaciones más · %s/u"] = "%d/%d points · ~%s%d|r more crafts · %s/ea",
  ["¡Ruta completada! %s de %d a %d."] = "Route completed! %s from %d to %d.",
  ["%s · sube el tope a %d%s"] = "%s · raises the cap to %d%s",
  [" · pide nivel %d"] = " · requires level %d",
  ["Se consigue una vez y no se gasta"] = "Obtained once and never used up",
  ["Ya la tienes"] = "You have it",
