  [" · +%d para %s"] = " · +%d for %s",
  ["Tienes %d/%d · faltan %s%d|r"] = "You have %d/%d · %s%d missing|r",
  ["La ruta busca otra receta en su lugar (por ejemplo, si no quieres ir a por este pergamino)."] = "The route finds another recipe instead (for example, if you don't want to go get this pattern).",
  ["Recetas quitadas de la ruta: %d"] = "Recipes removed from the route: %d",
  ["Avisos ocultos: %d"] = "Hidden tips: %d",
  ["Clic para volver a tenerlas en cuenta"] = "Click to bring them back",
  ["Quitadas de la ruta"] = "Removed from the route",
  -- Recipe you could make with what's in your bags
  [" y "] = " and ",
  ["Aprendida"] = "Learned",
  ["solo gastas %s en el instructor y el vendedor"] = "you only spend %s at the trainer and vendor",
  ["no gastas oro"] = "you spend no gold",
  [" (más el instructor, precio desconocido)"] = " (plus the trainer, price unknown)",
  ["Con lo que llevas podrías hacer %s (%d–%d): %s, pero usas %s, por los que te darían unos %s vendiéndolos."] = "With what you have you could make %s (%d–%d): %s, but you use %s, which would get you about %s if you sold them.",
  ["Hacerla con lo tuyo te sale unos %s mejor que venderlo y seguir la ruta. Pulsa Dejar ruta para incluirla."] = "Making it with yours is about %s better than selling it and following the route. Press Leave route to include it.",
  ["Vender lo tuyo y seguir la ruta te sale unos %s mejor."] = "Selling yours and following the route is about %s better.",
  ["Sale casi igual que venderlo, así que es más cómodo usar lo tuyo. Pulsa Dejar ruta para incluirla."] = "It's about the same as selling it, so using yours is easier. Press Leave route to include it.",
  ["Informar de un error"] = "Report a bug",
  ["¿Has visto información incorrecta, un error o algo nuevo que falte? Cuéntalo en el Discord con una captura de pantalla."] = "Found wrong information, a bug or something new that's missing? Report it on our Discord with a screenshot.",
  ["Discord (Ctrl+C para copiar):"] = "Discord (Ctrl+C to copy):",
  ["Errores, datos incorrectos o sugerencias: en nuestro Discord."] = "Bugs, wrong data or suggestions: on our Discord.",
  ["nunca"] = "never",
  ["Último intento (%s): %s"] = "Last attempt (%s): %s",
