  -- HeaderUI
  ["Sin resultados"] = "No results",
  ["Idioma del addon"] = "Addon language",
  ["Último escaneo: "] = "Last scan: ",
  ["El servidor solo permite un escaneo completo cada 15 min: podrás volver a escanear en %s."] = "The server only allows one full scan every 15 min: you can scan again in %s.",
  ["El servidor no respondió: solo permite un escaneo completo cada 15 min."] = "The server didn't answer: it only allows one full scan every 15 min.",
  ["Sin escanear"] = "Not scanned",
  ["Registro de errores vaciado."] = "Error log cleared.",
  ["Su ruta se calcula al abrirla (solo se calculan solas las profesiones que tienes)."] = "Its route is calculated when you open it (only the professions you have are calculated automatically).",
  ["Ningún error registrado."] = "No errors logged.",
  ["%d errores distintos registrados (el más reciente al final):"] = "%d different errors logged (most recent last):",
  ["Detalle completo en CraftersJournalDB.errorLog (SavedVariables, tras /reload). /cj errores borrar para vaciarlo."] = "Full details in CraftersJournalDB.errorLog (SavedVariables, after /reload). Type /cj errors clear to empty it.",
  ["Grabando los errores de Lua del addon hasta la próxima recarga (/reload). Repite lo que fallaba y mira /cj errores."] = "Recording the addon's Lua errors until the next reload (/reload). Repeat what was failing and check /cj errors.",
  ["Grabando los errores de Lua del addon hasta la próxima recarga (/reload)."] = "Recording the addon's Lua errors until the next reload (/reload).",
  ["Los errores de Lua del addon solo se graban con /cj errores grabar (hasta la próxima recarga)."] = "The addon's Lua errors are only recorded after /cj errors record (until the next reload).",
  ["Clic: vender %d por %s."] = "Click: sell %d for %s.",
  ["Vendiendo…"] = "Selling…",
  ["Para vender al vendedor, de tus bolsas:"] = "To sell to the vendor, from your bags:",
  ["Vendiendo %d objetos por %s..."] = "Selling %d items for %s...",
  ["Vender las %d (%s)"] = "Sell all %d (%s)",
  ["Instructor donde la viste"] = "Trainer where you saw it",
  ["Instructor del rango siguiente"] = "Next rank's trainer",
  ["Instructor del rango siguiente (el de su rango no la tiene)"] = "Next rank's trainer (its own rank's trainer doesn't have it)",
  ["Tu ruta de %s usaba %s, que este instructor no enseña: se calcula otra desde tu nivel."] = "Your %s route used %s, which this trainer doesn't teach: a new route is being calculated from your level.",
  ["Tu ruta de %s ya no se puede seguir con lo que enseña este instructor: se calcula otra desde tu nivel."] = "Your %s route can't be followed with what this trainer teaches: a new route is being calculated from your level.",
  ["No puedes aprender %s: ya tienes dos profesiones principales. Olvida una primero (desde su ventana de profesión)."] = "You can't learn %s: you already have two primary professions. Unlearn one first (from its profession window).",
  ["Vender al vendedor"] = "Sell to the vendor",
  ["Vendes %d × %s"] = "You sell %d × %s",
  ["Vender todo (%s)"] = "Sell all (%s)",
  ["Vender todo"] = "Sell all",
  ["Vende todo lo de esta lista: lo de tus bolsas que el vendedor compra, salvo lo que necesitan tus rutas empezadas, las herramientas, tu equipo (si lo activas en las opciones) y lo que marques con clic derecho (no venderlo nunca). Mira la lista antes de pulsar."] = "Sells everything on this list: whatever in your bags the vendor buys, except what your started routes need, profession tools, your own gear (if turned on in the options) and what you mark with right-click (never sell). Check the list before you click.",
  ["Para que esta ventana no salga: su engranaje, o las opciones del addon (engranaje de la ventana principal o /cj opciones)."] = "To stop this window from showing: its gear, or the addon options (gear on the main window or /cj options).",
  -- Options window
  ["General"] = "General",
  ["Casa de Subastas"] = "Auction House",
  ["Versión %s"] = "Version %s",
  ["Únete a nuestro Discord"] = "Join our Discord",
  ["Ideas, errores y novedades"] = "Ideas, bugs and news",
  ["Novedades, ideas y ayuda con el addon. Copia el enlace y ábrelo en tu navegador."] = "News, ideas and help with the addon. Copy the link and open it in your browser.",
  ["Ventanas, qué se propone vender, avisos y botón del minimapa."] = "Windows, what gets suggested for selling, alerts and the minimap button.",
  ["No vender tu equipo"] = "Don't sell your gear",
  ["Activado, el equipo ligado a ti (tu otro equipo, lo de las misiones) y el de los conjuntos del gestor de equipo no se propone vender (ni Vender todo lo vende); los verdes sin ligar de botín, lo que fabricas y lo gris, sí. Desactivado, se propone todo: lo que quieras guardar, clic derecho y no se vende nunca."] = "When on, soulbound gear (your other set, quest rewards) and gear in your equipment sets aren't suggested for selling (and Sell all doesn't sell them); unbound loot greens, what you craft and grey items still are. When off, everything is suggested: right-click what you want to keep and it's never sold.",
  ["Avisos en el chat"] = "Chat alerts",
  ["Vendedores de recetas de stock limitado"] = "Limited-stock recipe vendors",
  ["La ruta cuenta con ellos: suele ser lo más barato. Venden pocas y reponen con el tiempo, y a veces otros jugadores las acaparan para revenderlas."] = "The route counts on them: it's usually the cheapest option. They sell only a few and restock over time, and other players sometimes buy them all to resell.",
  ["La ruta no cuenta con ellos: esas recetas solo se consiguen por misión o en la Casa de Subastas; si no, se usa otra receta."] = "The route doesn't count on them: those recipes only come from a quest or the Auction House; otherwise it uses another recipe.",
  ["Su vendedor tiene stock limitado y desactivaste esos vendedores con su icono, arriba de la ruta."] = "Its vendor has limited stock and you turned those vendors off with their icon above the route.",
  ["Clic: abrir la receta y fabricar %d (con la profesión cerrada, el primer clic la abre)."] = "Click: open the recipe and craft %d (if the profession window is closed, the first click opens it).",
  ["Clic derecho: añadir sus materiales a la lista de compra."] = "Right-click: add its materials to the shopping list.",
  ["Ventana junto a la profesión"] = "Window next to professions",
  ["Al abrir una profesión: lo que la pestaña Ganar dinero propone fabricar de esa profesión. Clic en una fila para fabricarlo."] = "When you open a profession: what the Make money tab suggests crafting with it. Click a row to craft it.",
  ["Ganar dinero · %s: lo que da beneficio fabricar"] = "Make money · %s: what's profitable to craft",
  ["vender en la AH · invierte %s"] = "sell on the AH · invest %s",
  ["vender al vendedor · invierte %s"] = "sell to a vendor · invest %s",
  ["Clic: fabricar las de la fila (como mucho, las que dan tus materiales)."] = "Click: craft the row's amount (at most what your materials allow).",
  ["(%d más en la pestaña Ganar dinero)"] = "(%d more in the Make money tab)",
  ["Fabricarlo (sus materiales)"] = "Craft it (its materials)",
  ["Comprarlo hecho"] = "Buy it ready-made",
  ["sin precio"] = "no price",
  ["Lo más barato: comprarlo hecho."] = "Cheapest: buy it ready-made.",
  ["Lo más barato: fabricarlo."] = "Cheapest: craft it.",
  ["Tiene enfriamiento (una cada pocos días): se compra hecho si se puede."] = "Has a cooldown (one every few days): bought ready-made when possible.",
  ["Clic: comprarlo hecho en vez de fabricarlo."] = "Click: buy it ready-made instead of crafting it.",
  ["Clic: fabricarlo en vez de comprarlo hecho."] = "Click: craft it instead of buying it ready-made.",
  ["lo fabricas"] = "you craft it",
  ["lo compras hecho"] = "you buy it ready-made",
  [" · no es lo más barato"] = " · not the cheapest",
  [" · clic para cambiar"] = " · click to change",
  ["En la AH"] = "On the AH",
  ["Por el chat de comercio (sin comisión)"] = "Through trade chat (no cut)",
  ["Al vendedor"] = "To a vendor",
  ["Depósito: %s (%d subastas de %d h). Se devuelve si se vende: no resta del beneficio; lo pierdes si caduca."] = "Deposit: %s (%d auctions of %d h). You get it back if it sells, so it isn't taken off the profit; you lose it if it expires.",
  ["Vender en:"] = "Sell on:",
  ["AH · %d h"] = "AH · %d h",
  ["Cara a cara (comercio): sin comisión de la AH ni depósito."] = "Face to face (trade): no AH cut or deposit.",
  ["Fabricar más"] = "Craft more",
  ["Clic: escribir el precio por unidad"] = "Click: type the price per unit",
  ["Por ejemplo 6.5 (6s 50c) o 1g 20s. Vacío vuelve al precio automático; Escape no cambia nada."] = "For example 6.5 (6s 50c) or 1g 20s. Empty goes back to the automatic price; Escape changes nothing.",
  ["Fabricar menos"] = "Craft fewer",
  ["Con Mayús, de 5 en 5. Tu cantidad dura hasta el siguiente escaneo; luego vuelve a la recomendada."] = "Shift: 5 at a time. Your amount lasts until the next scan, then it goes back to the recommended one.",
  [" · más de lo recomendado (%d)"] = " · more than recommended (%d)",
  ["Fabrica %d: la cantidad la elegiste tú (recomendadas: %d). Vuelve a la recomendada con el siguiente escaneo."] = "Craft %d: you chose this amount (recommended: %d). It goes back to the recommended one with the next scan.",
  ["Más de lo recomendado: si no se venden, tienes el oro parado y puedes perder depósitos al caducar."] = "More than recommended: if they don't sell, your gold is tied up and you can lose deposits when they expire.",
  ["%s: quitada de la Lista de compra. Tu ruta sigue empezada; vuelve a ponerla desde la vista Materiales de la ruta."] = "%s: removed from the Shopping list. Your route is still started; add it back from the route's Materials view.",
  ["Quitar la lista de esta ruta. La ruta sigue empezada; se vuelve a poner desde su vista Materiales."] = "Remove this route's list. The route stays started; add it back from its Materials view.",
  ["Lista de compra · quitada"] = "Shopping list · removed",
  ["Pulsa para volver a ponerla"] = "Click to add it back",
  ["la quitaste con la X de la Lista de compra"] = "you removed it with the X in the Shopping list",
  [" · pide objetos"] = " · asks for items",
  [" · cadena de %d misiones"] = " · chain of %d quests",
  ["Pide: "] = "Asks: ",
  ["Antes hay que hacer 1 misión de su cadena, que también puede pedir objetos."] = "You need to do 1 earlier quest in its chain first, which may also ask for items.",
  ["Antes hay que hacer %d misiones de su cadena, que también pueden pedir objetos."] = "You need to do %d earlier quests in its chain first, which may also ask for items.",
  ["La ruta no le pone precio a lo que pide (casi todo se consigue matando criaturas). Si no te compensa, quítala con la X de la fila."] = "The route doesn't put a price on what it asks for (most of it drops from mobs). If it's not worth it for you, remove it with the X on the row.",
  ["stock limitado · no se cuentan"] = "limited stock · not used",
  ["X de la fila: quitar esta receta y que la ruta busque otra (se recupera con la fila de recetas quitadas)."] = "X on the row: remove this recipe and let the route pick another (bring it back from the removed recipes row).",
  ["Tras un escaneo: recetas de botín que te faltan y están en la AH, y si tu ruta empezada cuesta bastante más con los precios nuevos. Desactivados, la ruta lo sigue diciendo en su línea de estado."] = "After a scan: loot recipes you're missing that are on the AH, and whether your started route costs a lot more with the new prices. When off, the route still shows it in its status line.",
  ["Botón del minimapa"] = "Minimap button",
  ["El botón de Crafter's Journal junto al minimapa. También con /cj minimap."] = "The Crafter's Journal button by the minimap. Also with /cj minimap.",
  ["Tu equipo (ligado a ti o en un conjunto del gestor de equipo): no se propone venderlo, para no venderlo sin querer. Se cambia en /cj opciones."] = "Your gear (soulbound or in an equipment set): not suggested for selling, so you don't sell it by accident. Change it in /cj options.",
  ["tu equipo: no se vende"] = "your gear: not for sale",
  ["Ventana junto al vendedor"] = "Window next to vendors",
  ["Al abrir un vendedor: lo que te falta de la lista de compra y lo que puedes venderle, con los botones Comprar todo y Vender todo."] = "When you open a vendor: what you still need from your shopping list and what you can sell to them, with the Buy all and Sell all buttons.",
  ["Lista de compra junto a la Casa de Subastas"] = "Shopping list next to the Auction House",
  ["Tamaño de las tandas (recetas verdes)"] = "Batch size (green recipes)",
  ["En verde no todas las fabricaciones suben punto: la ruta compra para unas tantas y, al gastarlas, la siguiente. Más grande, menos viajes a la AH; más pequeña, menos material de sobra si tienes suerte."] = "On green recipes not every craft gives a point: the route buys for a number of crafts and, when you use them up, the next batch. Bigger means fewer trips to the AH; smaller means fewer leftover materials if you get lucky.",
  ["Cada tanda es de unas %d fabricaciones: se cambia en /cj opciones, Lista de compra."] = "Each batch is about %d crafts: change it in /cj options, Shopping list.",
  ["Al abrir la AH: los materiales de tu ruta que te faltan, para comprarlos. Desactivada, se sigue pudiendo abrir con el botón de encima de la AH."] = "When you open the AH: the materials your route still needs, ready to buy. When off, you can still open it with the button above the AH.",
  ["Vender en la AH desde tus bolsas"] = "Sell on the AH from your bags",
  ["Opciones"] = "Options",
  -- WhatsNew
  ["Novedades"] = "What's New",
  ["Crafter's Journal %s: esto es lo nuevo desde la última vez."] = "Crafter's Journal %s: here's what's new since last time.",
  ["¡Entendido!"] = "Got it!",
  ["Siguiente"] = "Next",
  ["Precios del vendedor, siempre los del juego"] = "Vendor prices, always the game's",
  ["El addon ya no deduce lo que paga el vendedor del dinero que te entra al vender: con dos ventas cobradas juntas podía apuntar el doble, y Ganar dinero prometía de más. Ahora usa siempre el precio del juego."] = "The addon no longer works out what vendors pay from the money you get when selling: two sales paid at once could make it note twice the price, and Make Money promised too much. It now always uses the game's price.",
  ["Aprender una receta, solo si compensa"] = "Learning a recipe only when it's worth it",
  ["La ruta ya no te manda al instructor a aprender una receta para unas pocas fabricaciones que ahorran unas monedas: esos puntos los hace con la receta de al lado, salvo que ahorre más de 5s."] = "The route no longer sends you to a trainer to learn a recipe for a few crafts that save a few coins: it does those points with the recipe next to it, unless learning it saves more than 5s.",
  ["Se ve cuándo esperar en la AH"] = "See when to wait at the AH",
  ["Mientras se escanea la AH, la ventana de vender queda tapada con un reloj de arena y el progreso: así no anuncias a precios viejos sin querer."] = "While the AH is being scanned, the sell window is covered by an hourglass and the progress, so you don't post at old prices by accident.",
  ["Nueva pestaña: Merchant's Favor"] = "New tab: Merchant's Favor",
  ["Con qué llenar tus Waylaid Crates al menor coste y qué cajas de la AH dan el Favor más barato por punto. Clic en una fila para añadirlo a la lista de compra."] = "What to fill your Waylaid Crates with for the least gold, and which AH crates give the cheapest Favor per point. Click a row to add it to the shopping list.",
  ["Más fluido"] = "Smoother",
  ["Sin tirones al acabar un escaneo ni al entrar, fabricar en serie va fluido y el addon apenas trabaja mientras juegas por el mundo."] = "No more hitches when a scan ends or when you log in, crafting in a series runs smoothly, and the addon barely works while you play out in the world.",
  ["Cuánto se tarda en fabricar"] = "How long crafting takes",
  ["Cada paso de la ruta dice cuánto se tarda en fabricarlo (en naranja si es lento) y el total, el de toda la ruta. \"Menos fabricaciones\" ahora también evita las recetas lentas."] = "Each route step says how long it takes to craft (in orange when it's slow), and the total shows the whole route. \"Fewer crafts\" now also avoids slow recipes.",
  ["Ganar dinero, más fiable"] = "Make Money, more reliable",
  ["Solo fabrica lo intermedio con recetas que sabes y dice qué fabricar antes. Enseña cuánto ya llevas en las bolsas, y las filas del lote no cambian de sitio al pulsar - o +."] = "It only crafts intermediates with recipes you know, and says what to craft first. It shows how much you already have in your bags, and batch rows no longer move when you press - or +.",
  ["Quitar una ventana, en un clic"] = "Turn off a window in one click",
  ["El engranaje de las ventanas junto al vendedor, la AH y la profesión abre un menú con \"No mostrar esta ventana\", sin buscarla en las opciones."] = "The gear on the windows next to the vendor, the AH and your profession opens a menu with \"Don't show this window\", without searching the options.",
  ["Buscar en la AH con Mayús+clic"] = "Search the AH with Shift-click",
  ["Mayús+clic en un objeto del addon lo busca en la AH (o lo enlaza en el chat). Y la lista de compra junto a la AH tiene una X en cada lista para quitarla."] = "Shift-click an item in the addon to search for it on the AH (or link it in chat). And the shopping list next to the AH has an X on each list to remove it.",
  ["Vista de desarrollo: no cuenta como vista."] = "Developer preview: not marked as seen.",
  ["Ahora en alemán y francés"] = "Now in German and French",
  ["Textos, recetas y objetos en alemán y francés, con los nombres del juego. Se cambia con el selector de idioma de arriba. Si ves una traducción mejorable, dínoslo en Discord."] = "Texts, recipes and items in German and French, with the game's own names. Switch with the language selector at the top. If a translation could be better, tell us on Discord.",
  ["Cada ventana, con su propia opción"] = "Every window has its own option",
  ["Las ventanas que salen solas junto al vendedor, la Casa de Subastas y la profesión tienen un engranaje que abre las opciones. La lista de compra y la de vender en la AH ya se quitan por separado."] = "The windows that open next to vendors, the Auction House and your profession now have a gear button that opens the options. The shopping list and the AH sell window can be turned off separately.",
  ["Confirmar antes de anunciar"] = "Confirm before listing",
  ["Al anunciar más de una unidad de golpe se pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón. Se puede desactivar."] = "When you list more than one unit at once, it asks first how many and at what price, so a stray click doesn't list a whole stack. You can turn this off.",
  ["La AH sin tirones"] = "No more AH stutter",
  ["Al acabar un escaneo (el tuyo o el de otro addon, como Auctionator) los precios se guardan poco a poco y el juego ya no se congela. Nueva opción para no leer los escaneos de otros addons."] = "When a scan finishes (yours or another addon's, like Auctionator), prices are saved bit by bit and the game no longer freezes. New option to stop reading other addons' scans.",
  ["Rutas sin enfriamientos"] = "Routes without cooldowns",
  ["Las transmutaciones y el Mooncloth tienen enfriamiento: la ruta ya no pide 186 transmutaciones seguidas. Como mucho las usa para un punto."] = "Transmutes and Mooncloth have cooldowns, so routes no longer ask for 186 transmutes in a row. They're used for one point at most.",
  ["Lista de compra en su sitio"] = "Shopping list stays in place",
  ["Al cerrar la ventana de vender en la AH, la lista de compra se pega a la AH y no deja un hueco."] = "Closing the AH sell window now moves the shopping list next to the AH instead of leaving a gap.",

  ["Confirmar antes de anunciar en la AH"] = "Confirm before listing on the AH",
  ["Al anunciar más de una unidad de golpe (ventana de vender, Inventario, ruta), pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón."] = "When you list more than one unit at once (sell window, Inventory, route), it asks first how many and at what price. That way a stray click doesn't list a whole stack.",
  ["Duración de las subastas"] = "Auction duration",
  ["Automática: 24 h lo que se vende bien y 8 h lo dudoso (si caduca, pierdes menos depósito). O la misma siempre: más corta, depósito más barato y vuelves a anunciar antes. Vale para la ventana de vender, el Inventario y la ruta."] = "Automatic: 24 h for what sells well and 8 h for the doubtful (if it expires, you lose less deposit). Or always the same one: shorter means a cheaper deposit and you relist sooner. Applies to the sell window, the Inventory and the route.",
  ["Automática"] = "Automatic",
  ["2 h"] = "2 h",
  ["8 h"] = "8 h",
  ["24 h"] = "24 h",
  ["Anunciar en la Casa de Subastas"] = "List on the Auction House",
  ["¿Anunciar %d × %s a %s cada uno (%d h)?"] = "List %d × %s at %s each (%d h)?",
  ["Clic: dejar de mostrar esta ventana, o ver todas las opciones."] = "Click: stop showing this window, or see all options.",
  ["No mostrar esta ventana"] = "Don't show this window",
  ["Se vuelve a activar en /cj opciones."] = "You can turn it back on in /cj options.",
  ["Todas las opciones"] = "All options",
  ["%s: desactivada. Vuelve a activarla en /cj opciones."] = "%s: turned off. Turn it back on in /cj options.",
  ["Esta ventana sale sola al abrir un vendedor. Si no la quieres, quítala en /cj opciones."] = "This window opens on its own when you visit a vendor. If you don't want it, turn it off in /cj options.",
  ["La lista de compra sale sola al abrir la Casa de Subastas. Si no la quieres, quítala en /cj opciones."] = "The shopping list opens on its own at the Auction House. If you don't want it, turn it off in /cj options.",
  ["La ventana de vender en la AH sale sola al abrir la Casa de Subastas. Si no la quieres, quítala en /cj opciones."] = "The sell window opens on its own at the Auction House. If you don't want it, turn it off in /cj options.",
  ["Esta ventana sale sola al abrir una profesión. Si no la quieres, quítala en /cj opciones."] = "This window opens on its own when you open a profession. If you don't want it, turn it off in /cj options.",
  ["Al abrir la AH: una ventana con lo de tus bolsas que se vende mejor en la AH. Clic en una fila para anunciarlo."] = "When you open the AH: a window with the items in your bags that sell better on the AH. Click a row to list it.",
  ["Botones de escanear de Crafter's Journal"] = "Crafter's Journal scan buttons",
  ["El botón Escanear de la cabecera del addon y el de encima de la AH, que además abre el addon. Piden el escaneo completo de Auctionator. Desactivados, se esconden si el botón Escanear de Auctionator hace el escaneo completo (su escaneo alternativo activado). Si no, porque Auctionator está en modo resumen (el de por defecto) o no está instalado, salen en gris con lo que falta: el addon solo se actualiza con escaneos completos. Ábrelo con /cj o el botón del minimapa."] = "The Scan button in the addon's header and the one above the AH, which also opens the addon. They start Auctionator's full scan. When off, they're hidden if Auctionator's Scan button does the full scan (its alternate scan mode turned on). If not, because Auctionator is in summary mode (its default) or isn't installed, they show greyed out with what's missing: the addon only updates with full scans. Open the addon with /cj or the minimap button.",
  ["Auctionator está en modo resumen: su botón Escanear no actualiza Crafter's Journal. Activa en las opciones de Auctionator «%s», o vuelve a mostrar los botones de escanear en las opciones de Crafter's Journal."] = "Auctionator is in summary mode: its Scan button doesn't update Crafter's Journal. Turn on \"%s\" in Auctionator's options, or show the scan buttons again in Crafter's Journal's options.",

