  ["Al pulsar Comprar todo en la ventana junto al vendedor, pregunta antes cuántos materiales compra y por cuánto."] = "When you click Buy all in the window next to the vendor, it asks first how many materials it buys and for how much.",
  ["Confirmar antes de vender todo al vendedor"] = "Confirm before selling everything to the vendor",
  ["Al pulsar el botón de vender al vendedor de la pestaña Inventario, pregunta antes cuántos objetos vende y por cuánto."] = "When you click the sell-to-vendor button in the Inventory tab, it asks first how many items it sells and for how much.",
  ["Mostrar las novedades al actualizar"] = "Show what's new after updating",
  ["Tras actualizar el addon, una ventana con lo nuevo de esa versión (una vez por versión). También se quita con su casilla \"No volver a mostrar\"."] = "After updating the addon, a window with what's new in that version (once per version). Also turned off with its \"Don't show again\" checkbox.",
  ["Ya no se mostrarán las novedades. Se vuelven a activar en /cj opciones (General)."] = "What's new won't show again. Turn it back on in /cj options (General).",
  ["No volver a mostrar"] = "Don't show again",
  ["Clic: seleccionarlo y marcarlo con una estrella (si está cerca)."] = "Click: target it and mark it with a star (if it's nearby).",
  ["Controles siempre visibles"] = "Controls always visible",
  ["Activado, los controles alrededor del asistente (flechas de pasos, modo de compra, saltar, cerrar) se ven siempre. Desactivado, se despliegan al pasar el ratón por el asistente y se pliegan al salir."] = "On, the controls around the assistant (step arrows, buy mode, skip, close) always show. Off, they slide out when you hover the assistant and fold away when you leave.",
  ["Clic para marcarlo"] = "Click to mark them",
  ["Encima del asistente, una flecha que te lleva al instructor o al vendedor del paso, con las yardas y el tiempo. Al pulsar el banner se marca además el camino como en la ventana del addon."] = "Above the assistant, an arrow that takes you to the step's trainer or vendor, with the yards and time. Clicking the banner also sets the way as in the addon window.",
  ["Saltar"] = "Skip",
  ["ruta entera"] = "whole route",
  ["ya puedes · antes de %d"] = "you can now · before %d",
  ["aprende también: %s"] = "also learn: %s",
  ["Comprado: %s"] = "Bought: %s",
  ["Buzón"] = "Mailbox",
  ["+%d después"] = "+%d later",
  ["Guarda las otras %d: no se sabe si se venden bien, así que anuncia unas pocas y, cuando se vendan, las siguientes (aunque sea en varios días). En la AH valen más que en el vendedor."] = "Keep the other %d: it's not clear they sell well, so list a few and, once they sell, the next ones (even over several days). They're worth more on the AH than at the vendor.",
  ["Siguiendo el consejo (AH y vendedor)"] = "Following the advice (AH and vendor)",
  ["Lo del vendedor es seguro; lo de la AH, si se vende"] = "The vendor part is certain; the AH part, if it sells",
  ["con AH: "] = "with AH: ",
  ["Vendiendo al vendedor (seguro)"] = "Selling to the vendor (certain)",
  ["El segundo total cuenta lo que la vista %s aconseja anunciar en la AH a su precio actual. No es seguro: depende de que se venda, a ese precio y antes de que caduque la subasta. Lo del vendedor sí es seguro."] = "The second total counts what the %s view advises posting on the AH, at its current price. It isn't guaranteed: it depends on it selling, at that price, before the auction expires. The vendor part is certain.",
  ["Para seguir fabricando, compra más"] = "To keep crafting, buy more",
  ["Clic: aprenderlo en este instructor."] = "Click: learn it from this trainer.",
  ["Este instructor no lo enseña (o aún no te llega el nivel)."] = "This trainer doesn't teach it (or your level isn't high enough yet).",
  ["Buzón más cercano"] = "Nearest mailbox",
  ["Recoge el correo"] = "Collect your mail",
  ["Lo comprado en la AH: "] = "Bought on the AH: ",
  ["%d objetos comprados en la AH"] = "%d items bought on the AH",
  ["Lo que compraste en la AH para esta ruta. Este paso se da por hecho cuando lo tienes en las bolsas."] = "What you bought on the AH for this route. This step is done once it's in your bags.",
  ["Comprada en la AH · apréndela antes de fabricar"] = "Bought on the AH · learn it before crafting",
  ["aprende %s primero"] = "learn %s first",
  ["Compra detectada: %s ×%d. Cuenta ya para la ruta y la lista de compra."] = "Purchase detected: %s ×%d. It already counts for the route and the shopping list.",
  ["compra también %s"] = "also buy %s",
  ["fabrica aquí hasta %s"] = "craft here up to %s",
  ["Los pasos de compra y la Lista de compra piden solo lo del tramo en el que estás."] = "The buy steps and the Shopping list only ask for the stage you're on.",
  ["Los pasos de compra y la Lista de compra piden lo que falta para toda la ruta, de una vez."] = "The buy steps and the Shopping list ask for everything missing for the whole route, at once.",
  ["Es el modo de ahora."] = "This is the current mode.",
  ["Clic: cambiar a este modo."] = "Click: switch to this mode.",
  ["Cómo funciona el asistente"] = "How the assistant works",
  ["Abrir la ruta en la ventana"] = "Open the route in the window",
  ["La ruta entera, en el paso en el que estás: ahí puedes quitar una receta, cambiar las opciones de la ruta o dejarla."] = "The whole route, at the step you're on: there you can remove a recipe, change the route options or leave it.",
  ["Clic: la explicación, paso a paso."] = "Click: the full explanation, step by step.",
  ["Te guía paso a paso por tu ruta empezada, sin abrir la ventana: enseña el mismo paso que la vista Ruta."] = "It guides you step by step through your started route without opening the window: it shows the same step as the Route view.",
  ["Bloquearlo o sacarlo solo al empezar una ruta: /cj opciones, Asistente de ruta."] = "Lock it, or show it only when you start a route: /cj options, Route Assistant.",
  ["Un clic en el banner hace lo que toca"] = "One click on the banner does what's next",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra; con el banco, saca a las bolsas justo lo que falta. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "With the AH open, it buys the next material; at a vendor, it buys from them; at the bank, it moves just what you're missing into your bags. With nothing open, it takes you to the nearest NPC. It never buys without your click.",
  ["El color dice qué toca"] = "The color tells you what's next",
  ["¿Por qué pide más fabricaciones de las que me dan los materiales?"] = "Why does it ask for more crafts than my materials allow?",
  ["La ruta compra por tandas: en las recetas amarillas y verdes no todas suben punto. \"Esta tanda: N\" es para cuántas te llega lo que llevas. Con suerte basta; si no, al acabarla te manda a comprar más."] = "The route buys in batches: on yellow and green recipes not every craft gives a point. \"This batch: N\" is how many what you carry covers. With luck it's enough; if not, when it runs out it sends you to buy more.",
  ["¿Qué significa el número de \"Fabrica N×\"?"] = "What does the number in \"Craft N×\" mean?",
  ["Es lo que te falta de media para acabar el paso, según los puntos que te quedan. Baja con cada fabricación; si tienes mala suerte y el punto no sube, se queda quieto hasta que lo subas."] = "It's how many crafts you need on average to finish the step, based on the points you still need. It goes down with each craft; if you're unlucky and the point doesn't come, it stays put until you get it.",
  ["Lo tengo de otro sitio (comercio, hermandad, otro personaje)"] = "I got it elsewhere (trade chat, guild, another character)",
  ["En el paso de compra, pulsa Saltar: lo da por comprado en este tramo. Lo comprado en la AH ya cuenta aunque siga en el correo."] = "On the buy step, click Skip: it counts it as bought for this stage. What you buy on the AH already counts while it's still in the mail.",
  ["¿Y si fabrico otra cosa o voy por otro orden?"] = "What if I craft something else or go in another order?",
  ["La ruta mira tu nivel y tus bolsas, no lo que fabricaste: se pone al día sola. Si gastaste materiales, te mandará a comprar lo que falte."] = "The route looks at your skill level and your bags, not at what you crafted: it catches up on its own. If you used up materials, it will send you to buy what's missing.",
  ["Comprar o ir al banco"] = "Buy or go to the bank",
  ["Ir a un PNJ"] = "Go to an NPC",
  ["La flecha te lleva al PNJ"] = "The arrow takes you to the NPC",
  ["Sale cuando el paso tiene un PNJ: verde si vas bien, roja si vas al revés. También lo marca en el mapa y el minimapa. En otro continente te dice qué barco o zepelín tomar."] = "It shows up when the step has an NPC: green when you're heading the right way, red when you're going the wrong way. It's also marked on the map and minimap. On another continent it tells you which boat or zeppelin to take.",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "With the AH open, it buys the next material; at a vendor, it buys from them. With nothing open, it takes you to the nearest NPC. It never buys without your click.",
  ["Comprar"] = "Buy",
  ["Comprar: por tramos"] = "Buy: by stage",
  ["Comprar: ruta entera"] = "Buy: whole route",
  ["Saltar este paso"] = "Skip this step",
  ["Recuperar"] = "Restore",
  ["Recuperar este paso"] = "Restore this step",
  ["Lo saltaste: vuelve a pedirte comprarlo."] = "You skipped it: it asks you to buy it again.",
  ["Si te equivocas, vuelve a él con la flecha de paso anterior y pulsa Recuperar."] = "If you made a mistake, go back to it with the previous-step arrow and press Restore.",
  ["Saltado · Recuperar lo vuelve a poner"] = "Skipped · Restore brings it back",
  ["Lo das por comprado y pasa al siguiente paso. Para lo que el addon no ve (el chat de comercio, el banco de hermandad, un alter). Solo en este tramo."] = "Counts it as bought and moves on to the next step. For what the addon can't see (trade chat, guild bank, an alt). Only for this stage.",
  ["Lo comprado en la AH ya cuenta aunque siga en el correo."] = "What you buy on the AH already counts while it's still in the mail.",
  ["Quitar de Ganar dinero"] = "Remove from Make money",
  ["No volver a proponer esta receta aquí: por ejemplo, si pide una estación que no tienes. Se recupera con la fila de recetas quitadas, al final de la lista."] = "Stop suggesting this recipe here: for example, if it needs a station you don't have. Bring it back with the removed recipes row at the end of the list.",
  ["Recetas quitadas de Ganar dinero: %d"] = "Recipes removed from Make money: %d",
  ["Quitadas de Ganar dinero"] = "Removed from Make money",
  ["En las recetas verdes (y a veces en las amarillas) no todas las fabricaciones suben punto, así que la ruta compra por tandas: cuando gastas una, te trae a comprar la siguiente y luego vuelves a fabricar."] = "On green recipes (and sometimes yellow ones) not every craft gives a skill-up, so the route buys in batches: when you use one up, it brings you to buy the next one and then you go back to crafting.",
  ["BETA"] = "BETA",
  ["Asistente de ruta (beta)"] = "Route assistant (beta)",
  ["Está en pruebas. Si ves algo raro, abre un post en el canal de bugs de nuestro Discord: el enlace está en el botón Informar de un error, arriba a la izquierda de la ventana del addon."] = "It's being tested. If you see something odd, open a post in the bugs channel on our Discord: the link is behind the Report a bug button, at the top left of the addon window.",
  ["Si no quieres usarlo, desactívalo en /cj opciones, Asistente de ruta."] = "If you don't want to use it, turn it off in /cj options, Route assistant.",
  ["los %d que hacen falta"] = "all %d you need",
  ["%d en total · tienes %d"] = "%d in total · you have %d",
  ["%d en total"] = "%d in total",
  ["Demanda (TSM, región): ~%s vendidos al día, tasa de venta %s"] = "Demand (TSM, region): ~%s sold per day, sale rate %s",
  ["Demanda (TSM): sin datos de este objeto (¿la app de TSM está al día?)"] = "Demand (TSM): no data for this item (is the TSM app up to date?)",
  ["TSM: en la región se vende de media a %s, bastante menos que los %s con los que se cuenta aquí."] = "TSM: across the region it sells for %s on average, well below the %s used here.",
  ["Poca demanda según TSM y otra alerta en contra: aunque el margen parezca bueno, probablemente no lo venderás."] = "Low demand according to TSM plus another warning sign: even if the margin looks good, you probably won't sell it.",
  ["TSM: en la región se venden ~%s al día: como mucho lo que se vende en %d días."] = "TSM: ~%s sell per day across the region: at most what sells in %d days.",
  ["Usar la demanda de TSM"] = "Use TSM demand data",
  ["Si tienes TSM con su app de escritorio: cuántos se venden al día en la región y qué parte de lo que se anuncia se vende. Es una alerta más de mercado y no se proponen más de los que se venden en 2 días. Tus escaneos siguen mandando."] = "If you have TSM with its desktop app: how many sell per day across the region and what share of listings sell. It adds one more market warning sign and never suggests more than what sells in 2 days. Your own scans still take priority.",
  ["receta con enfriamiento, una cada vez."] = "recipe with a cooldown, one at a time.",
  ["No se sabe aún si su enfriamiento está listo: al abrir la profesión se comprueba (si no lo está, sale del lote)."] = "Not known yet whether its cooldown is ready: it's checked when you open the profession (if it isn't, it leaves the batch).",
  [" · enfriamiento: ¿listo?"] = " · cooldown: ready?",
  [" · enfriamiento listo"] = " · cooldown ready",
  ["Abre la profesión para saber si está listo"] = "Open the profession to see if it's ready",
  ["Listo: está en el lote de hoy"] = "Ready: it's in today's batch",
  ["Demanda de TSM: vendidos al día, mínimo"] = "TSM demand: minimum sold per day",
  ["Por debajo, alerta de poca demanda (y no se propone aprender la receta). Cuenta toda la región: tu reino vende como mucho eso."] = "Below this, a low-demand warning (and learning the recipe isn't suggested). It counts the whole region: your realm sells at most that.",
  ["Demanda de TSM: tasa de venta mínima"] = "TSM demand: minimum sale rate",
  ["Qué parte de lo que se anuncia acaba vendiéndose (1 = todo). Por debajo, alerta de poca demanda."] = "What share of listings ends up selling (1 = all of them). Below this, a low-demand warning.",
  ["%s al día"] = "%s per day",
  ["No cuenta"] = "Off",
  ["Tiene enfriamiento (una cada vez): lo que cuesta aprenderla se recupera en %d fabricaciones."] = "Has a cooldown (one at a time): what it costs to learn is paid back in %d crafts.",
  ["Tiene enfriamiento: se puede fabricar una cada vez."] = "Has a cooldown: you can craft one at a time.",
  [" · con enfriamiento"] = " · has a cooldown",
  ["Este vendedor no tiene: %s. Sigue la fila para ir a otro."] = "This vendor doesn't have: %s. Follow the row to go to another one.",
  ["Nuevo: asistente de ruta (beta)"] = "New: route assistant (beta)",
  ["Con una ruta empezada, un banner pequeño te dice qué toca: fabricar, comprar en la AH o al vendedor, recoger el correo o entrenar. Un clic lo hace o te lleva. Se abre con el botón junto a Dejar ruta o con /cj mini."] = "With a route started, a small banner tells you what's next: craft, buy on the AH or from a vendor, collect your mail or train. One click does it or takes you there. Open it with the button next to Leave route or with /cj mini.",
  ["Cuánto se tarda en fabricar"] = "How long crafting takes",
  ["Cada paso de la ruta dice cuánto tardas en fabricarlo, y la franja de arriba el tiempo de toda la ruta."] = "Each route step says how long it takes to craft, and the bar at the top shows the time for the whole route.",
  ["Lo que sacas vendiendo en la AH"] = "What you get selling on the AH",
  ["Bajo el total de la ruta, \"con AH\" dice lo que te quedaría si vendes lo fabricado como aconseja la vista Profit, en la AH y al vendedor."] = "Under the route total, \"with AH\" shows what you'd end up with if you sell what you craft as the Profit view suggests, on the AH and to the vendor.",
  ["Menos verdes en las rutas"] = "Fewer greens in routes",
  ["La ruta prefiere recetas seguras a tramos largos en verde: menos fabricaciones y menos viajes a comprar, por muy poco oro más."] = "Routes prefer safe recipes over long green stretches: fewer crafts and fewer trips to buy, for very little extra gold.",
  ["Vender, más fácil"] = "Selling made easier",
  ["Vender todo vende todo de un clic, y lo que no tiene un precio fiable en la AH va al vendedor. Con Ctrl+clic derecho en una fila lo pasas de la AH al vendedor o al revés."] = "Sell all sells everything in one click, and items without a reliable AH price go to the vendor. Ctrl+right-click a row to move it from the AH to the vendor or back.",
  ["Compras por tandas en verde"] = "Batch buying on green recipes",
  ["En las recetas verdes compra por tandas, con algo de margen, y \"esta tanda: N\" dice para cuántas te llega lo que llevas. El tamaño de la tanda se cambia en /cj opciones, Lista de compra."] = "On green recipes it buys in batches, with some margin, and \"this batch: N\" tells you how many crafts what you carry covers. Change the batch size in /cj options, Shopping list.",
  ["Enfriamientos en el lote de hoy"] = "Cooldowns in today's batch",
  ["Las transmutaciones y la Mooncloth que tienes listas entran en el Lote de hoy, una cada vez, y vuelven solas cuando están otra vez listas. También salen en las recetas que podrías aprender."] = "Transmutes and Mooncloth that are ready now go into Today's batch, one at a time, and come back by themselves when they're ready again. They also show up in the recipes you could learn.",
  ["Confirmar antes de vender o comprar todo"] = "Confirm before selling or buying everything",
  ["Vender todo, Comprar todo y vender al vendedor desde el Inventario preguntan antes. Cada aviso se quita con \"No volver a mostrar\" y se vuelve a activar en las opciones."] = "Sell all, Buy all and selling to the vendor from the Inventory now ask first. Each prompt can be turned off with \"Don't show again\" and turned back on in the options.",
  ["Quita recetas de Ganar dinero"] = "Remove recipes from Make money",
  ["Con la X de una fila, Ganar dinero deja de proponerte esa receta (por ejemplo, si pide una estación que no tienes). Se recupera con la fila del final de la lista."] = "With the X on a row, Make money stops suggesting that recipe (for example, if it needs a station you don't have). Get it back with the row at the end of the list.",
  ["Demanda de TSM"] = "TSM demand",
  ["Si tienes TSM con su app, Ganar dinero tiene en cuenta cuántas se venden al día en tu región y no te propone fabricar más de lo que se vende. Los mínimos se ajustan en las opciones de Ganar dinero."] = "If you have TSM with its app, Make money takes into account how many sell per day in your region and never suggests crafting more than what sells. The minimums are set in the Make money options.",
  ["La bolsa de componentes cuenta"] = "Your reagent bag counts",
  ["Lo que llevas en la bolsa de componentes cuenta en la ruta, el Inventario y Ganar dinero, y \"Recoge el correo\" se completa aunque lo recogido vaya a esa bolsa."] = "What you carry in your reagent bag counts in the route, the Inventory and Make money, and \"Collect your mail\" completes even when what you collect goes into that bag.",
  ["Recetas con dos herramientas"] = "Recipes with two tools",
  ["Los cascos de ingeniería piden el Blacksmith Hammer y la Arclight Spanner, y la ruta ya pide las dos."] = "Engineering helmets need both the Blacksmith Hammer and the Arclight Spanner, and the route now asks for both.",
  ["Gasta lo que sobra"] = "Use up what's left over",
  ["Al acabar un paso, si te sobran materiales y fabricar con ellos deja más que venderlos, la ruta te lo propone."] = "When a step is done, if you have materials left over and crafting with them earns more than selling them, the route suggests it.",
  ["Recetas de lo intermedio"] = "Recipes for intermediates",
  ["Si algo intermedio pide una receta que no sabes (Stonescale Oil), la ruta tiene una fila para aprenderla y cuenta su precio."] = "If an intermediate needs a recipe you don't know (Stonescale Oil), the route has a row to learn it and counts its price.",
  ["Confirmar al anunciar, más fiable"] = "More reliable posting confirmation",
  ["El Sí anuncia antes de cerrar el aviso, el aviso se cierra al cerrar la AH o el vendedor, y ya no dice \"Anunciados\" si la AH no responde."] = "Yes posts before closing the prompt, the prompt closes when you close the AH or the vendor, and it no longer says \"Posted\" when the AH doesn't answer.",
  ["Rutas que no se quedan en el 99%"] = "Routes no longer stuck at 99%",
  ["Si el cálculo de una ruta falla, la página lo dice en vez de quedarse en \"Calculando la ruta… 99%\". E Ingeniería 1-300 vuelve a calcularse rápido."] = "If calculating a route fails, the page says so instead of staying on \"Calculating the route… 99%\". And Engineering 1-300 is quick to calculate again.",
  ["Herramientas en la lista de la compra"] = "Tools on the shopping list",
  ["Si un paso pide una herramienta que no llevas (Arclight Spanner), va a la lista de la compra en vez de darla por hecha."] = "If a step needs a tool you don't carry (Arclight Spanner), it goes on the shopping list instead of being taken for granted.",
  ["Transmutaciones en otros idiomas"] = "Transmutes in other languages",
  ["Con el juego en español, alemán o francés, la ruta ya no pide 186 transmutaciones seguidas: reconoce su enfriamiento."] = "With the game in Spanish, German or French, the route no longer asks for 186 transmutes in a row: it recognizes their cooldown.",
  ["Sin errores en mazmorras"] = "No errors in dungeons",
  ["Las compras de la AH se leen del chat solo con la AH abierta: en mazmorras y en combate ya no salen errores."] = "AH purchases are read from chat only while the AH is open: no more errors in dungeons and in combat.",
  -- Investments tab (InvestUI.lua, Invest.lua)
  ["Inversiones"] = "Investments",
  ["Precio al apuntar una compra o venta"] = "Price when noting down a purchase or sale",
  ["Lo que escribes en el precio: el total (lo que pagaste por todo) o el precio por unidad. En la ventana de compra o venta lo puedes cambiar cada vez."] = "What you type as the price: the total (what you paid for all of it) or the price per unit. You can switch it each time in the purchase or sale window.",
  ["Último escaneo (%s): nada a este precio; lo más barato, %s"] = "Last scan (%s): nothing at this price; cheapest, %s",
  ["Último escaneo (%s): %s u a este precio o menos"] = "Last scan (%s): %s at this price or less",
  [" · el resto desde %s"] = " · the rest from %s",
  ["Farmeado"] = "Farmed",
  ["Nueva pestaña: Inversiones"] = "New tab: Investments",
  ["Apunta lo que compras para revender (cantidad y precio, por unidad o total) y te dice tu precio medio y cuánto ganas o pierdes, neto de la comisión de la AH (5%)."] = "Note down what you buy to resell (quantity and price, per unit or total) and it tells you your average price and how much you're up or down, net of the AH cut (5%).",
  ["hoy"] = "today",
  ["ayer"] = "yesterday",
  ["Escribe la cantidad y el precio (por ejemplo 2.5 = 2s 50c, o 1g 20s). Si lo has farmeado, 0."] = "Type the quantity and the price (for example 2.5 = 2s 50c, or 1g 20s). If you farmed it, 0.",
  ["Solo tienes %d para vender."] = "You only have %d to sell.",
  ["Escribe la cantidad: un número entero mayor que 0."] = "Type the quantity: a whole number greater than 0.",
  ["Escribe el precio: por ejemplo 2.5 (2s 50c) o 1g 20s."] = "Type the price: for example 2.5 (2s 50c) or 1g 20s.",
  ["Precio"] = "Price",
  ["Cancelar"] = "Cancel",
  ["Vender"] = "Sell",
  ["Añadir"] = "Add",
  ["Añadir: escribe un nombre"] = "Add: type a name",
  ["Hay una venta de más unidades de las que tenías: revisa los movimientos en el detalle."] = "There's a sale of more units than you had: check the transactions in the detail.",
  ["Vendido todo (%d u)."] = "All sold (%d).",
  ["Realizado"] = "Realized",
  ["Tienes %d u"] = "You have %d",
  ["media %s"] = "average %s",
  ["Invertido"] = "Invested",
  ["Precio (%s)"] = "Price (%s)",
  ["Valor bruto"] = "Gross value",
  ["Comisión de la AH (5%)"] = "AH cut (5%)",
  ["Neto"] = "Net",
  ["Si vendes"] = "If sold",
  ["Bajada de hoy sin confirmar: puede ser una subasta suelta muy barata."] = "Today's drop isn't confirmed yet: it may be a single very cheap auction.",
  ["Clic: ver el detalle"] = "Click: see the detail",
  ["Revisa los movimientos"] = "Check the transactions",
  ["%d movimientos"] = "%d transactions",
  ["Vendido todo · %d u"] = "All sold · %d",
  ["%d u · media %s"] = "%d · average %s",
  ["Vale hoy"] = "Worth today",
  ["Neto tras la AH (5%)"] = "Net after AH (5%)",
  ["Revisa los movimientos (%d)"] = "Check the transactions (%d)",
  ["Cerradas (%d)"] = "Closed (%d)",
  ["%s a la venta"] = "%s for sale",
