  -- Options: Investments, hide list-view columns
  ["Columnas de la lista"] = "List columns",
  ["Clic en una columna para ocultarla de la vista de lista (o volver a mostrarla). El nombre del objeto gana el sitio."] = "Click a column to hide it from the list view (or show it again). The item name gets the space.",
